from pathlib import Path
import json
ROOT=Path(__file__).resolve().parent;SRC=ROOT/'src';DOCS=ROOT/'docs'
read=lambda n:(SRC/n).read_text(encoding='utf-8')
css=read('style.css')
courses=[dict(id='images',path='image-processing',title='معالجة الصور الرقمية',storageKey='pixel-quest-course-v1',sourceLabel='صور مقرر معالجة الصور الـ45',guideUrl='../assets/study-guide.pdf',sourcesUrl='../assets/original-pages.pdf',guideLabel='الدليل المفصل PDF',sourcesLabel='الصور الأصلية المرتبة',warning='راجع حدود القناع والتقريب والعتبة. NOT ليس ضرباً في−1. بعض حسابات المصدر مصححة ومبينة في الدليل.'),dict(id='security',path='information-security',title='أمن المعلومات والتشفير',storageKey='pixel-quest-security-v1',sourceLabel='خمسة عروض وملفا Word: 169 شريحة',guideUrl='reference.html',sourcesUrl='sources.html',guideLabel='المرجع المنظم لجميع الأفكار',sourcesLabel='تتبع الملفات وتصحيحات المحاضرات',warning='المتماثل يستخدم مفتاحاً سرياً مشتركاً وليس «مفتاحاً عاماً». MD5 دالة تجزئة وله تصادمات؛ لا يصلح لتوقيعات حديثة أو تخزين كلمات السر الخام. اتجاه تشفير بلايفر يمين وأسفل؛ بعض تسميات شريحة الحل معكوسة. راجع المصدر والتصحيح معاً.')]
def page(title,body,script=''):
 return '<!doctype html><html lang="ar" dir="rtl"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#171925"><title>'+title+'</title><style>'+css+'</style></head><body>'+body+('<script>'+script.replace('</script','<\\/script')+'</script>' if script else '')+'</body></html>'
for course in courses:
 path=DOCS/course['path'];path.mkdir(exist_ok=True);security=course['id']=='security'
 labs=read('labs.js').replace('\nrender();','\n')
 if security:labs=labs.replace('function labHTML(', 'function imageLabHTML(')
 js='const COURSE='+json.dumps(course,ensure_ascii=False)+';\n'
 js+='\n;\n'.join(([read('security-crypto.js')] if security else [])+[read('security-content.js' if security else 'content.js'),read('logic.js'),read('app.js'),labs]+([read('security-labs.js')] if security else []))+ '\n;render();'
 (path/'index.html').write_text(page('Pixel Quest | '+course['title'],'<div id="app"></div><noscript>تحتاج اللعبة إلىJavaScript.</noscript>',js),encoding='utf-8')
hub='''<div class="shell"><aside class="sidebar" id="library-side"><div class="brand"><div class="logo">▦</div><div class="brand-name">PIXEL QUEST<small>مكتبة موادك الدراسية</small></div></div><nav class="nav"><button class="active">مكتبة المواد</button></nav><div class="side-scroll"><p class="side-label">YOUR SUBJECTS</p><a class="course-switch" href="image-processing/">معالجة الصور الرقمية</a><a class="course-switch" href="information-security/">أمن المعلومات والتشفير</a></div><div class="side-footer"><strong>نفس المكان، طرق تعلم مختلفة</strong>لكل مادة مستويات وتجارب وأسئلة وتقدم مستقل.</div></aside><main class="main"><header class="topbar"><div class="top-context"><button class="mobile-menu" id="library-menu" aria-label="فتح قائمة المواد" aria-expanded="false">☰</button><strong>مكتبة المواد الدراسية</strong></div><span class="mode-tag">مادتان · تجربة واحدة مألوفة</span></header><div class="container"><section class="library-top"><div class="eyebrow">YOUR LEARNING LIBRARY</div><h1>اختر مادتك.<br>وتعلّم بالطريقة التي تناسبها.</h1><p>فكرة قصيرة، تجربة مناسبة للمادة، ثم سؤال يختبر الفهم والتطبيق. كل مقرر مستقل بمراجعة أخطائه، ومرجعه، وتحديه النهائي.</p></section><div class="library-grid"><article class="subject-card"><div class="eyebrow">IMAGE PROCESSING</div><h2>معالجة الصور الرقمية</h2><p>البكسلات والطيف، التكبير والتلفيف، البتات والجبر والمنطق، والمرشحات وتقليل البيانات.</p><span class="mode-tag">16 مستوى · 48 فكرة</span><p class="small" style="margin-top:14px">مختبرات الصور والمصفوفات والتلاعب بالشدة.</p><div class="progressbar"><span id="image-bar" style="width:0%"></span></div><p class="small" id="image-progress"></p><a class="btn primary" href="image-processing/">افتح مادة الصور</a></article><article class="subject-card" style="border-color:#8970b4;background:linear-gradient(150deg,#322742,#1e2534)"><div class="eyebrow">INFORMATION SECURITY</div><h2>أمن المعلومات والتشفير</h2><p>مخاطر وهوية وحوادث وشبكات وبرمجيات خبيثة، ثم قيصر والبصمات والتوقيع وبلايفر وهيل خطوة بخطوة.</p><span class="mode-tag">32 مستوى · 96 فكرة · 7 ملفات</span><p class="small" style="margin-top:14px">قرارات أمنية، ترتيب إجراءات، مربع بلايفر، ومصفوفات هيل.</p><div class="progressbar"><span id="security-bar" style="width:0%"></span></div><p class="small" id="security-progress"></p><a class="btn primary" href="information-security/">ابدأ مادة الأمن</a></article></div><div class="bottom-note"><div><strong>تقدمك القديم محفوظ</strong>مادة الصور تستخدم مفتاح الحفظ نفسه. لكل مادة حفظ مستقل في هذا المتصفح؛ التقدم لا ينتقل تلقائياً بين الهاتف والحاسوب.</div></div><div class="bottom-note"><div><strong>الإنهاء بالتطبيق، لا بتقليب البطاقات</strong>الخطأ يقود إلى شرح ومحاولة أخرى. تتبع المصادر يبين ما غُطي وأين صُححت عبارة متعارضة. إكمال اللعبة لا يضمن درجة الامتحان.</div></div></div></main></div>'''
hubjs="""for(const [id,key,total] of [['image','pixel-quest-course-v1',48],['security','pixel-quest-security-v1',96]]){try{const s=JSON.parse(localStorage.getItem(key)||'{}');const n=Math.min(total,Object.values(s.done||{}).filter(x=>x===true).length);document.getElementById(id+'-bar').style.width=(100*n/total)+'%';document.getElementById(id+'-progress').textContent=n+' / '+total+' فكرة مكتسبة في هذا المتصفح';}catch{document.getElementById(id+'-progress').textContent='التخزين المحلي غير متاح؛ يمكنك التعلم خلال الجلسة.';}}document.getElementById('library-menu').addEventListener('click',function(){const open=document.getElementById('library-side').classList.toggle('open');this.setAttribute('aria-expanded',String(open));});"""
(DOCS/'index.html').write_text(page('Pixel Quest | مكتبة المواد',hub,hubjs),encoding='utf-8')
(DOCS/'.nojekyll').touch()
print('Built subject library and both standalone courses.')
